import argparse
import json
from pathlib import Path
import sys
import tempfile
from . import TeamPlanner

ACTIONS = {'member': 'add_member', 'activity': 'create_activity', 'enroll': 'enroll', 'enroll-batch': 'enroll_batch', 'preview-enroll': 'preview_enrollments', 'cancel': 'cancel_enrollments', 'transfer': 'transfer_enrollment', 'transfer-batch': 'transfer_enrollments', 'preview-transfer': 'preview_transfer_enrollments', 'split-activity': 'split_activity', 'reschedule': 'reschedule_activity', 'reschedule-batch': 'reschedule_activities', 'preview-reschedule': 'preview_reschedule_activities', 'roster': 'roster', 'list': 'activities', 'complete': 'record_completion', 'complete-batch': 'record_completions', 'correct-completions': 'correct_completions', 'completions': 'completions', 'merge': 'merge_member', 'merge-activities': 'merge_activities', 'schedule': 'member_schedule', 'enrollment-options': 'enrollment_options', 'training-progress': 'training_progress', 'training-requirements': 'training_requirements', 'training-validity': 'training_validity', 'training-timeline': 'training_validity_timeline', 'training-coverage': 'training_coverage', 'preview-absence-coverage': 'preview_absence_coverage', 'training-alerts': 'training_alerts', 'renewal-options': 'training_renewal_options', 'export-schedule': 'export_schedule'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for member in samples("members.json"):
        app.add_member(**member)
    app.create_activity(**samples("activity.json"))
    app.enroll(**samples("enrollment.json"))
    # 2026-10-15 的虚构安排：A-002 与 A-001 同日，由小陈和小周报满；
    # 小陈在 A-003 已登记完成，报名仍然保留，当天原本互为冲突。
    app.create_activity("A-002", "安全规范", "2026-10-15", 2)
    app.create_activity("A-003", "团队协作", "2026-10-15", 2)
    app.enroll("A-002", "M-001")
    app.enroll("A-002", "M-003")
    app.enroll("A-003", "M-001")
    app.record_completion("A-003", "M-001", "2026-10-15")
    # 一次取消两场，标识带首尾空白也会先去除；满员的 A-002 释放席位，
    # 返回顺序与输入一致，且各活动只移除小陈本人。
    cancelled = app.cancel_enrollments("M-001", [" A-002 ", "A-001"])
    if [a["activity_id"] for a in cancelled] != ["A-002", "A-001"]:
        raise ValueError("demo: cancelled activities must follow the input order")
    if cancelled[0]["participants"] != ["M-003"] or cancelled[1]["participants"] != []:
        raise ValueError("demo: only the cancelling member is removed")
    # 取消后小陈只剩已完成的 A-003，同日冲突随之消失。
    schedule = app.member_schedule("M-001")
    if [r["activity_id"] for r in schedule] != ["A-003"] or schedule[0]["conflict_activity_ids"] != []:
        raise ValueError("demo: same-day conflicts must disappear after cancellation")
    # 释放的席位立即可用：小林报进原本满员的 A-002，小陈重新报回 A-001。
    app.enroll("A-002", "M-002")
    app.enroll("A-001", "M-001")
    # 小陈在 A-003 已有本人完成记录：整次取消被拒绝，两边名单均不变，
    # 完成记录继续保留。
    try:
        app.cancel_enrollments("M-001", ["A-001", "A-003"])
    except ValueError:
        pass
    else:
        raise ValueError("demo: cancelling a completed activity must fail")
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: rosters must stay unchanged after a rejected cancellation")
    if [m["member_id"] for m in app.roster("A-003")["members"]] != ["M-001"]:
        raise ValueError("demo: the completed activity roster must stay unchanged")
    if [r["activity_id"] for r in app.completions("M-001")] != ["A-003"]:
        raise ValueError("demo: completion records must be kept")
    # 整组完成登记：2026-10-15 当天两场虚构培训（小陈的 A-001、小周的 A-002）
    # 一次性提交，允许跨活动、跨成员，标识带首尾空白会先去除；返回顺序与输入
    # 一致，字段与单条 complete 相同，两场都应登记成功。
    recorded = app.record_completions([
        {"activity_id": " A-001 ", "member_id": "M-001", "completed_on": "2026-10-15"},
        {"activity_id": "A-002", "member_id": " M-003 ", "completed_on": "2026-10-15"},
    ])
    if [r["activity_id"] for r in recorded] != ["A-001", "A-002"]:
        raise ValueError("demo: batch records must follow the input order")
    if recorded[0] != {"activity_id": "A-001", "member_id": "M-001", "completed_on": "2026-10-15", "title": "新成员产品介绍", "on": "2026-10-15"}:
        raise ValueError("demo: batch record fields must match the single complete result")
    # 末条失败（小陈在 A-003 已有完成记录）时整组拒绝：首条小林在 A-002 的
    # 新记录也不得写入，数据文件字节不变。
    before = app.path.read_bytes()
    try:
        app.record_completions([
            {"activity_id": "A-002", "member_id": "M-002", "completed_on": "2026-10-15"},
            {"activity_id": "A-003", "member_id": "M-001", "completed_on": "2026-10-15"},
        ])
    except ValueError:
        pass
    else:
        raise ValueError("demo: a batch with a failing last record must be rejected")
    if before != app.path.read_bytes():
        raise ValueError("demo: a rejected batch must leave data.json bytes unchanged")
    if app.completions("M-002") != []:
        raise ValueError("demo: no record from the rejected batch may survive")
    # 完成登记不取消报名：两场新完成的培训仍然占位、名单顺序不变。
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: completion keeps the enrollment")
    return app.roster("A-001")

def main(argv=None):
    parser = argparse.ArgumentParser(description="团队培训安排")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(TeamPlanner(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = TeamPlanner(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

from pathlib import Path
import json
import os
import tempfile
from datetime import date

COLLECTIONS = ("members", "activities", "completions")

class JsonStore:
    def __init__(self, root):
        self.root = Path(root)
        self.path = self.root / "data.json"

    def _read(self):
        # A missing file is an empty history. Any other filesystem problem
        # (permissions, data.json being a directory, ...) stays an OSError.
        try:
            raw = self.path.read_bytes()
        except FileNotFoundError:
            return {}
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("data.json must be a valid UTF-8 file")
        try:
            value = json.loads(text)
        except json.JSONDecodeError:
            raise ValueError("data.json must be valid JSON")
        if not isinstance(value, dict):
            raise ValueError("stored document must be an object")
        # The whole history is validated on every read, so a query can never
        # hide an unrelated broken record behind its filters.
        validate_document(value)
        return value

    def _write(self, value):
        # Validate before touching the filesystem: invalid data never creates
        # a missing directory or file and never replaces an existing file.
        validate_document(value)
        self.root.mkdir(parents=True, exist_ok=True)
        fd, name = tempfile.mkstemp(prefix=".data-", suffix=".json", dir=self.root)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
                stream.write("\n")
            os.replace(name, self.path)
        finally:
            if os.path.exists(name):
                os.unlink(name)

def text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(label + " must be a nonempty string")
    return value.strip()

def identifier(value, label):
    # Stored keys and participant ids are matched exactly, never trimmed:
    # surrounding whitespace or an empty string are invalid on disk.
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(label + " must be a nonempty string without surrounding whitespace")
    return value

def positive(value, label):
    if type(value) is not int or value <= 0:
        raise ValueError(label + " must be a positive integer")
    return value

def day(value, label):
    # Only a real YYYY-MM-DD calendar date is accepted: no other types,
    # no surrounding whitespace, no relaxed parsing.
    if not isinstance(value, str) or len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError(label + " must be a YYYY-MM-DD date string")
    try:
        parsed = date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except (ValueError, OverflowError):
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    if parsed.isoformat() != value:
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    return parsed.isoformat()

def validate_document(data):
    # Business consistency check for a whole historical document. Missing
    # collections are empty; present ones must be JSON objects (null is not an
    # empty object). Extra fields on the document, members and activities are
    # allowed and left untouched by the caller.
    if not isinstance(data, dict):
        raise ValueError("stored document must be an object")
    for name in COLLECTIONS:
        if name in data and not isinstance(data[name], dict):
            raise ValueError(name + " must be an object")
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})

    for key, member in members.items():
        identifier(key, "member key")
        if not isinstance(member, dict):
            raise ValueError("member entry must be an object")
        if not isinstance(member.get("member_id"), str) or member["member_id"] != key:
            raise ValueError("member_id must match the member object key")
        if not isinstance(member.get("name"), str) or not member["name"].strip():
            raise ValueError("member name must be a nonblank string")

    activity_dates = {}
    for key, activity in activities.items():
        identifier(key, "activity key")
        if not isinstance(activity, dict):
            raise ValueError("activity entry must be an object")
        if not isinstance(activity.get("activity_id"), str) or activity["activity_id"] != key:
            raise ValueError("activity_id must match the activity object key")
        if not isinstance(activity.get("title"), str) or not activity["title"].strip():
            raise ValueError("activity title must be a nonblank string")
        activity_dates[key] = day(activity.get("on"), "on")
        positive(activity.get("capacity"), "capacity")
        participants = activity.get("participants")
        if not isinstance(participants, list):
            raise ValueError("participants must be an array")
        seen = set()
        for member_id in participants:
            identifier(member_id, "participant id")
            if member_id in seen:
                raise ValueError("participants must not contain duplicate member ids")
            if member_id not in members:
                raise ValueError("participant references an unknown member")
            seen.add(member_id)
        if len(participants) > activity["capacity"]:
            raise ValueError("participant count must not exceed capacity")

    for activity_id, done in completions.items():
        identifier(activity_id, "completion activity key")
        if not isinstance(done, dict):
            raise ValueError("completion records must be an object")
        if activity_id not in activities:
            raise ValueError("completion references an unknown activity")
        enrolled = set(activities[activity_id]["participants"])
        for member_id, completed_on in done.items():
            identifier(member_id, "completion member id")
            if member_id not in enrolled:
                raise ValueError("completion references a member not enrolled in the activity")
            completed_on = day(completed_on, "completed_on")
            if date.fromisoformat(completed_on) < date.fromisoformat(activity_dates[activity_id]):
                raise ValueError("completed_on must be on or after the activity date")

def training_coverage(self, groups, from_on, to_on, minimum_count, member_ids=None):
    # Read-only headcount reconciliation over a fixed date range: each day
    # of the closed from_on..to_on range is judged exactly like
    # training_validity with that day as the cutoff, and a member counts
    # once on a day when every selected group is valid for them that day.
    # Consecutive days with the same qualified members merge into one
    # maximal closed period; a same-size swap of people still splits, a
    # mere change of the underlying completion record does not. Groups
    # exist only for this call; current rosters, profiles and completion
    # records are used as they are, never reconstructed historically, and
    # the current date is never consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days"}:
            raise ValueError("each group must contain only group_id, activity_ids and valid_days")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in training_validity, an activity belongs to exactly one
            # group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    # The expected headcount is a non-boolean positive integer; it may
    # exceed the number of selected members.
    minimum_count = positive(minimum_count, "minimum_count")
    # member_ids follows training_validity_timeline exactly: omitted or
    # null means every member, an empty array means no members at all.
    if member_ids is None:
        selected_member_ids = None
    elif not isinstance(member_ids, list):
        raise ValueError("member_ids must be an array or null")
    else:
        selected_member_ids = []
        seen_members = set()
        for member_id in member_ids:
            member_id = text(member_id, "member_id")
            if member_id in seen_members:
                raise ValueError("member_ids must not contain duplicates")
            seen_members.add(member_id)
            selected_member_ids.append(member_id)
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Every reference is validated even when nobody is selected.
    for _, activity_ids, _ in selected_groups:
        for activity_id in activity_ids:
            if activities.get(activity_id) is None:
                raise ValueError("unknown activity")
    if selected_member_ids is None:
        # Everyone, by ascending identifier.
        ordered_member_ids = sorted(members)
    else:
        for member_id in selected_member_ids:
            if member_id not in members:
                raise ValueError("unknown member")
        ordered_member_ids = selected_member_ids
    start = date.fromisoformat(from_on)
    end = date.fromisoformat(to_on)

    def valid_intervals(member_id, activity_ids, valid_days):
        # The eligible records are exactly training_validity's: a stored
        # completion only exists for enrolled members, and a missing
        # record is the same as no record. Records become eligible on
        # their completion date, so a future record never hides an older
        # expired one.
        records_by_date = {}
        for activity_id in activity_ids:
            activity = activities[activity_id]
            if member_id not in activity.get("participants", []):
                continue
            completed_on = completions.get(activity_id, {}).get(member_id)
            if completed_on is not None:
                records_by_date.setdefault(date.fromisoformat(completed_on), []).append(
                    (activity["on"], activity_id)
                )
        # The selected record can only change when a record with a later
        # completion date becomes eligible; an equal completion date
        # breaks by activity date and activity id, both ascending, exactly
        # as in training_validity. Only the takeover dates matter here,
        # not which record wins.
        takeovers = sorted(records_by_date)
        intervals = []
        for index, completed in enumerate(takeovers):
            segment_end = takeovers[index + 1] - timedelta(days=1) if index + 1 < len(takeovers) else date.max
            # The expiry is the completion day plus valid_days calendar
            # days; the expiry day itself is expired. An expiry past
            # date.max is beyond every possible range end, so the record
            # stays valid through the range instead of raising.
            try:
                expires = completed + timedelta(days=valid_days)
            except OverflowError:
                expires = None
            valid_end = segment_end if expires is None else min(segment_end, expires - timedelta(days=1))
            frm, to = max(completed, start), min(valid_end, end)
            if frm <= to:
                intervals.append((frm, to))
        return intervals

    def intersect(first, second):
        # Both lists hold sorted, disjoint closed intervals; the result
        # keeps only the days covered by both.
        merged = []
        i = j = 0
        while i < len(first) and j < len(second):
            frm = max(first[i][0], second[j][0])
            to = min(first[i][1], second[j][1])
            if frm <= to:
                merged.append((frm, to))
            if first[i][1] < second[j][1]:
                i += 1
            else:
                j += 1
        return merged

    # Per member, the days on which every selected group is valid at once.
    qualified = []
    for member_id in ordered_member_ids:
        intervals = valid_intervals(member_id, selected_groups[0][1], selected_groups[0][2])
        for _, activity_ids, valid_days in selected_groups[1:]:
            if not intervals:
                break
            intervals = intersect(intervals, valid_intervals(member_id, activity_ids, valid_days))
        qualified.append(intervals)

    # Sweep the range: the qualified set can only change where a member's
    # interval starts or ends, so the days between consecutive edges share
    # one set. Every edge lies inside the range, so no date overflows.
    edges = set()
    for intervals in qualified:
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    boundaries = [start] + sorted(edges)
    periods = []
    for index, frm in enumerate(boundaries):
        to = boundaries[index + 1] - timedelta(days=1) if index + 1 < len(boundaries) else end
        ids = tuple(
            member_id
            for member_id, intervals in zip(ordered_member_ids, qualified)
            if any(f <= frm <= t for f, t in intervals)
        )
        if periods and periods[-1][2] == ids:
            # Same qualified members on the following days extend the open
            # period instead of starting a new one.
            periods[-1][1] = to
        else:
            periods.append([frm, to, ids])
    return {
        "from_on": from_on,
        "to_on": to_on,
        "minimum_count": minimum_count,
        "periods": [
            {
                "from_on": frm.isoformat(),
                "to_on": to.isoformat(),
                "valid_member_ids": list(ids),
                "valid_count": len(ids),
                "shortage_count": max(0, minimum_count - len(ids)),
            }
            for frm, to, ids in periods
        ],
    }

def preview_absence_coverage(self, groups, from_on, to_on, minimum_count, absences=None, member_ids=None):
    # Read-only absence preview over training_coverage: the qualified
    # members per day are computed exactly as in training_coverage, and
    # the requested absences only mark some of them away for this call.
    # The absences exist only for this preview: nothing is ever stored,
    # and enrollments, completion records and profiles are used as they
    # are, never reconstructed historically; the current date is never
    # consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days"}:
            raise ValueError("each group must contain only group_id, activity_ids and valid_days")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in training_coverage, an activity belongs to exactly one
            # group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    minimum_count = positive(minimum_count, "minimum_count")
    # The absence list is required: null (or a missing argument) is
    # rejected, while an empty array previews a plain coverage run.
    if absences is None or not isinstance(absences, list):
        raise ValueError("absences must be an array")
    absence_entries = []
    for item in absences:
        if not isinstance(item, dict) or set(item) != {"member_id", "from_on", "to_on"}:
            raise ValueError("each absence must contain only member_id, from_on and to_on")
        absence_member_id = text(item["member_id"], "member_id")
        absence_from = day(item["from_on"], "from_on")
        absence_to = day(item["to_on"], "to_on")
        # Whole-day closed intervals; a reversed range is rejected.
        if absence_from > absence_to:
            raise ValueError("from_on must be on or before to_on")
        absence_entries.append((absence_member_id, absence_from, absence_to))
    # member_ids follows training_coverage exactly: omitted or null means
    # every member, an empty array means no members at all.
    if member_ids is None:
        selected_member_ids = None
    elif not isinstance(member_ids, list):
        raise ValueError("member_ids must be an array or null")
    else:
        selected_member_ids = []
        seen_members = set()
        for member_id in member_ids:
            member_id = text(member_id, "member_id")
            if member_id in seen_members:
                raise ValueError("member_ids must not contain duplicates")
            seen_members.add(member_id)
            selected_member_ids.append(member_id)
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Every reference is validated even when nobody is selected and every
    # absence falls outside the range.
    for _, activity_ids, _ in selected_groups:
        for activity_id in activity_ids:
            if activities.get(activity_id) is None:
                raise ValueError("unknown activity")
    if selected_member_ids is None:
        # Everyone, by ascending identifier.
        ordered_member_ids = sorted(members)
